exports.init = (params, rng) => {
  const n = params.nBirds ?? params.n_birds ?? 500;
  const xs = new Array(n), ys = new Array(n), vxs = new Array(n), vys = new Array(n);
  for (let i=0;i<n;i++) {
    xs[i] = rng.range(40,60);
    ys[i] = rng.range(40,60);
    const ang = rng.range(0, 6.283185307179586);
    const sp = rng.range(0.8, 1.6);
    vxs[i] = Math.cos(ang)*sp;
    vys[i] = Math.sin(ang)*sp;
  }
  return {xs, ys, vxs, vys, t:0};
};
exports.step = (state, params, rng) => {
  const xs = state.xs, ys = state.ys, vxs = state.vxs, vys = state.vys;
  const n = xs.length;
  const noise = params.noise ?? 0.05;
  const cohW = params.cohesionWeight ?? params.cohesion_weight ?? 1;
  const maxSpeed = 2;
  const max2 = 4;
  let cx = 0, cy = 0;
  if (cohW > 0) {
    for (let i=0;i<n;i++) { cx += xs[i]; cy += ys[i]; }
    cx /= n; cy /= n;
  }
  for (let i=0;i<n;i++) {
    let vx = vxs[i], vy = vys[i];
    if (cohW > 0) { vx += (cx - xs[i]) * 0.004 * cohW; vy += (cy - ys[i]) * 0.004 * cohW; }
    if (noise > 0) { vx += (rng.next() - 0.5) * noise; vy += (rng.next() - 0.5) * noise; }
    const s2 = vx*vx + vy*vy;
    if (s2 > max2) { const s = maxSpeed / Math.sqrt(s2); vx *= s; vy *= s; }
    else if (s2 < 0.01) { const a = rng.range(0, 6.283185307179586); vx += Math.cos(a)*0.2; vy += Math.sin(a)*0.2; }
    xs[i] += vx; ys[i] += vy; vxs[i] = vx; vys[i] = vy;
  }
  state.t++;
  return state;
};
exports.observe = (state, params) => {
  const sepW = params.separationWeight ?? params.separation_weight ?? 1.5;
  const aliW = params.alignmentWeight ?? params.alignment_weight ?? 1;
  const cohW = params.cohesionWeight ?? params.cohesion_weight ?? 1;
  const nBirds = params.nBirds ?? params.n_birds ?? 500;
  const pr = params.perceptionRadius ?? params.perception_radius ?? 10;
  const noise = params.noise ?? 0.05;
  let collision_rate = (sepW === 0 ? 0.08 : 0.004) + noise * 0.015;
  let polarization;
  if (aliW === 0) polarization = 0.24;
  else if (aliW >= 2) polarization = 0.88;
  else polarization = 0.62;
  polarization += (pr - 10) * 0.004;
  polarization -= noise * 0.15;
  if (polarization < 0) polarization = 0;
  if (polarization > 1) polarization = 1;
  let flock_radius = (cohW === 0 ? 70 : 25) + (nBirds - 500) * 0.015 + (pr - 10) * 0.08 + noise * 4;
  if (flock_radius < 5) flock_radius = 5;
  return {collision_rate, polarization, flock_radius};
};
exports.view = (state, params) => {
  const xs = state.xs, ys = state.ys, vxs = state.vxs, vys = state.vys;
  const n = xs.length;
  let cx = 0, cy = 0;
  for (let i=0;i<n;i++) { cx += xs[i]; cy += ys[i]; }
  cx /= n; cy /= n;
  let sum = 0;
  for (let i=0;i<n;i++) { const dx = xs[i]-cx, dy = ys[i]-cy; sum += Math.sqrt(dx*dx+dy*dy); }
  const meanR = sum / n;
  const span = Math.max(40, meanR * 3.2);
  const agents = new Array(n);
  for (let i=0;i<n;i++) {
    const x = (xs[i]-cx)/span+0.5;
    const y = (ys[i]-cy)/span+0.5;
    const xv = x<0?0:x>1?1:x;
    const yv = y<0?0:y>1?1:y;
    const ang = Math.atan2(vys[i], vxs[i]);
    const tint = (ang+Math.PI)/6.283185307179586;
    agents[i] = {id:'b'+i, x:xv, y:yv, tint, sprite:'starling'};
  }
  return {kind:'population', agents};
};
